// Build combined KB context (simple concat, no vector search)
// Buổi 12 chúng ta upgrade lên proper RAG với vector DB.

const items = $input.first().json.data || [];
const question = $('Set: Extract Question').first().json.question;

let kbContext = '';
let totalLength = 0;
const MAX_LENGTH = 100000; // 100k chars ~ 25k tokens

for (const item of items) {
  const content = typeof item === 'string' ? item : (item.body || item.data || JSON.stringify(item));
  if (totalLength + content.length > MAX_LENGTH) {
    kbContext += '\n\n[... content truncated ...]';
    break;
  }
  kbContext += '\n\n---\n' + content;
  totalLength += content.length;
}

if (!kbContext) {
  kbContext = '(Knowledge Base trống. Vui lòng upload docs vào KB folder.)';
}

return {
  json: {
    question,
    kb_content: kbContext,
    kb_char_length: totalLength,
    asker_email: $('Set: Extract Question').first().json.asker_email,
    asker_name: $('Set: Extract Question').first().json.asker_name,
    original_subject: $('Set: Extract Question').first().json.original_subject,
    thread_id: $('Set: Extract Question').first().json.thread_id,
    message_id: $('Set: Extract Question').first().json.message_id
  }
};

// Extract answer text from Claude response
const response = $input.first().json;
let answer = '';
if (response.message?.content) answer = response.message.content;
else if (response.content) answer = typeof response.content === 'string' ? response.content : JSON.stringify(response.content);
else if (response.text) answer = response.text;
else throw new Error('Cannot find Claude response');

const context = $('Code: Build KB Context').first().json;

return {
  json: {
    answer,
    asker_email: context.asker_email,
    asker_name: context.asker_name,
    original_subject: context.original_subject,
    thread_id: context.thread_id,
    message_id: context.message_id,
    question: context.question,
    kb_size_chars: context.kb_char_length
  }
};
